                if isinstance(v, str) and len(v) > 200:
                    print(f"  {k}: {v[:200]}...")
                elif isinstance(v, list) and len(v) > 3:
                    print(f"  {k}: [{v[0]}, ... ] (len={len(v)})")
                else:
                    print(f"  {k}: {v}")
