cd /tmp && cat << 'EOF' > fetch_stac.py
import urllib.request
import json

url = "https://raw.githubusercontent.com/amazon-science/MultiTurnAgentAttack/main/data/STAC_benchmark_data.json"
try:
    with urllib.request.urlopen(url, timeout=60) as response:
        raw = response.read().decode()
        data = json.loads(raw)
        if isinstance(data, list):
            print(f"Total entries: {len(data)}")
            print(f"\nFirst entry keys: {list(data[0].keys())}")
            # Print first entry structure
            sample = data[0]
            for k, v in sample.items():
                if isinstance(v, str) and len(v) > 300:
                    print(f"  {k}: (str, len={len(v)}) {v[:300]}...")
                elif isinstance(v, list):
                    print(f"  {k}: (list, len={len(v)})")
                    if len(v) > 0:
                        item = v[0]
                        if isinstance(item, dict):
                            print(f"    [0] keys: {list(item.keys())}")
                            for ik, iv in item.items():
                                if isinstance(iv, str) and len(iv) > 200:
                                    print(f"      {ik}: {iv[:200]}...")
                                else:
                                    print(f"      {ik}: {iv}")
                        else:
                            print(f"    [0]: {str(item)[:200]}")
                elif isinstance(v, dict):
                    print(f"  {k}: (dict, keys={list(v.keys())})")
                    for dk, dv in v.items():
                        if isinstance(dv, str) and len(dv) > 200:
                            print(f"    {dk}: {dv[:200]}...")
                        elif isinstance(dv, list):
                            print(f"    {dk}: (list, len={len(dv)})")
                            if len(dv) > 0 and isinstance(dv[0], dict):
                                print(f"      [0] keys: {list(dv[0].keys())}")
                        else:
                            print(f"    {dk}: {dv}")
                else:
                    print(f"  {k}: {v}")
        elif isinstance(data, dict):
            print(f"Top keys: {list(data.keys())}")
except Exception as e:
    print(f"Error: {e}")
